artifacts=[]

def artifact(identifier,path,kind,description,command=None,result=None,environment=None):
    value={'id':identifier,'kind':kind,'path':PREFIX+'/'+path,'sha256':digest(BASE/path),'description':description}
    if kind=='execution':value.update(command=command,result=result,environment=environment or probe['environment'])
    artifacts.append(value)
    return identifier

