claims=[]
def ref(source,locator,supports):return {'source_id':source,'locator':locator,'supports':supports}
def claim(identifier,kind,statement,location,evidence,artifact_ids,scope,expected=None,observed=None,denominators=None):
    c={'id':identifier,'kind':kind,'statement':statement,'location':location,'status':'verified','evidence':evidence,'artifact_ids':artifact_ids,'scope':scope}
    if kind in ['software','numeric','empirical']:
        c['verification']={'method':'executed','expected':expected or statement,'observed':observed or '指定實際核對命令exit 0；對應artifact保有原命令、輸入、assertions及真實結果。','details':scope+' 個別來源定位與artifact保留可追溯核對。'}
        if kind=='numeric':c['verification']['tolerance']='精確相等'
        if kind=='empirical':c['verification']['denominators']=denominators
    claims.append(c)

